import{_ as t,a as o,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Build a Storefront","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/shop/build-a-storefront.md","filePath":"api/workflows/shop/build-a-storefront.md","lastUpdated":1787290888000}'),s={name:"api/workflows/shop/build-a-storefront.md"};function i(c,e,n,h,l,p){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="build-a-storefront" tabindex="-1">Build a Storefront <a class="header-anchor" href="#build-a-storefront" aria-label="Permalink to &quot;Build a Storefront&quot;">​</a></h1><p>The <strong>complete storefront blueprint</strong> — every screen a shopper sees and the Shop API behind it, from the homepage to a placed order and the customer account. Use this as the map; for the two deepest flows, the focused <a href="/api/workflows/shop/cart.html">Cart</a> and <a href="/api/workflows/shop/checkout.html">Checkout</a> workflow pages carry the step-by-step call sequence.</p><p>Every request carries the <code>X-STOREFRONT-KEY</code> header; customer-scoped steps also carry <code>Authorization: Bearer &lt;token&gt;</code>. Open each linked page for the exact request/response shape.</p><h2 id="_0-context-locale-currency-channel" tabindex="-1">0. Context (locale / currency / channel) <a class="header-anchor" href="#_0-context-locale-currency-channel" aria-label="Permalink to &quot;0. Context (locale / currency / channel)&quot;">​</a></h2><p>Optional per-request headers <code>X-LOCALE</code>, <code>X-CURRENCY</code>, <code>X-CHANNEL</code> control what content the API returns. Discover valid values:</p><ul><li><a href="/api/rest-api/shop/channels/get-channels.html">Get Channels</a> — the store&#39;s sales channels; each channel lists its allowed <strong>currencies</strong> and <strong>locales</strong>.</li><li><a href="/api/rest-api/shop/locales/get-locales.html">Get Locales</a> — available languages (with <code>direction</code> for RTL).</li></ul><h2 id="_1-homepage" tabindex="-1">1. Homepage <a class="header-anchor" href="#_1-homepage" aria-label="Permalink to &quot;1. Homepage&quot;">​</a></h2><p>The landing screen is built from admin-managed content, not just products:</p><ul><li><strong>CMS pages</strong> (About, Privacy, Terms, custom landing copy) — the admin authors these; the storefront reads them via the <a href="/api/graphql-api/shop/cms-pages/">CMS Pages query (GraphQL)</a>. Render them as static pages and footer links.</li><li><strong>Theme customizations</strong> (hero image carousel, static blocks, featured/category carousels, footer links) — the homepage layout the admin configures. Read with <a href="/api/rest-api/shop/theme-customizations/get-theme-customizations.html">Get Theme Customizations</a>. Each block tells you what to render (a product-carousel block gives you the product ids to fetch; an image block gives banners).</li><li><strong>Navigation</strong> — <a href="/api/rest-api/shop/categories/get-categories.html">Get Categories</a> for the menu, or <a href="/api/rest-api/shop/categories/get-category-tree.html">Category Tree</a> for a nested megamenu.</li></ul><h2 id="_2-catalog" tabindex="-1">2. Catalog <a class="header-anchor" href="#_2-catalog" aria-label="Permalink to &quot;2. Catalog&quot;">​</a></h2><ul><li><strong>Category page</strong> — <a href="/api/rest-api/shop/categories/get-categories.html">Get Categories</a> for the category, then list its products (step below) filtered by that category.</li><li><strong>Product listing</strong> — <a href="/api/rest-api/shop/products/get-products.html">Get Products</a>, paginated with <code>?page=</code>, <code>?per_page=</code>, <code>?sort=</code>. Scope and filter it with <code>?category_id=</code>, <code>?price=10,200</code> (min,max), <code>?new=1</code>, <code>?featured=1</code>, <code>?type=</code>, and any attribute code (<code>?color=3&amp;size=6</code>). The complete parameter list is on <a href="/api/rest-api/shop/products/search-product.html">Search Products</a>.</li><li><strong>Category children</strong> — <code>?parent_id=N</code> (REST) or <code>treeCategories(parentId: N)</code> (GraphQL). The GraphQL <code>categories</code> field has <strong>no</strong> <code>parentId</code> argument.</li><li><strong>Search</strong> — <a href="/api/rest-api/shop/products/search-product.html">Search Products</a> — the same endpoint with <code>?query=</code>; composes with the filters above.</li><li><strong>Filters (faceting sidebar)</strong> — <a href="/api/rest-api/shop/attributes/get-attributes.html">Get Attributes</a> (<code>isFilterable: 1</code>) and <a href="/api/rest-api/shop/attributes/get-attribute-options.html">Attribute Options</a> give you the filter codes and option ids to feed the product-listing filters above (color, size, brand, price).</li><li><strong>Product detail page</strong> — <a href="/api/rest-api/shop/products/get-product.html">Get Product</a> for a single product: price, images, description, and type-specific data. Configurable / bundle / grouped / downloadable products expose their extra structure via <a href="/api/rest-api/shop/products/product-subresources.html">product sub-resources</a> and <a href="/api/rest-api/shop/products/product-type-subresources.html">type sub-resources</a>; bookable products via <a href="/api/rest-api/shop/products/get-booking-slots.html">booking slots</a>.</li><li><strong>Product reviews</strong> — show and collect ratings: <a href="/api/rest-api/shop/product-reviews/get-product-reviews.html">Get Product Reviews</a> · <a href="/api/rest-api/shop/product-reviews/create-product-review.html">Create Product Review</a> (logged-in customer).</li></ul><h2 id="_3-shopper-engagement" tabindex="-1">3. Shopper engagement <a class="header-anchor" href="#_3-shopper-engagement" aria-label="Permalink to &quot;3. Shopper engagement&quot;">​</a></h2><ul><li><strong>Wishlist</strong> (logged-in) — <a href="/api/rest-api/shop/wishlist/list.html">List</a> · <a href="/api/rest-api/shop/wishlist/toggle.html">Add / Toggle</a> · <a href="/api/rest-api/shop/wishlist/move-to-cart.html">Move to Cart</a>.</li><li><strong>Compare</strong> — <a href="/api/rest-api/shop/compare/list.html">List</a> · <a href="/api/rest-api/shop/compare/create.html">Add</a> · <a href="/api/rest-api/shop/compare/delete.html">Remove</a>.</li><li><strong>Newsletter</strong> — <a href="/api/rest-api/shop/newsletter/subscribe.html">Subscribe</a>.</li></ul><h2 id="_4-authenticate-the-customer" tabindex="-1">4. Authenticate the customer <a class="header-anchor" href="#_4-authenticate-the-customer" aria-label="Permalink to &quot;4. Authenticate the customer&quot;">​</a></h2><p>For cart-to-order and the account area, log the customer in and keep the token:</p><ul><li><a href="/api/rest-api/shop/customers/customer-login.html">Customer Login</a> → <code>data.token</code> → send as <code>Authorization: Bearer &lt;token&gt;</code>.</li><li>New customers: <a href="/api/rest-api/shop/customers/customer-registration.html">Customer Registration</a>.</li><li>Guests can still order without an account — see the Cart workflow&#39;s guest path.</li></ul><h2 id="_5-cart" tabindex="-1">5. Cart <a class="header-anchor" href="#_5-cart" aria-label="Permalink to &quot;5. Cart&quot;">​</a></h2><p>The full cart sequence (guest / customer, add / update, coupons, <strong>merge on login</strong>) is its own page: <strong><a href="/api/workflows/shop/cart.html">Cart workflow →</a></strong>.</p><h2 id="_6-checkout" tabindex="-1">6. Checkout <a class="header-anchor" href="#_6-checkout" aria-label="Permalink to &quot;6. Checkout&quot;">​</a></h2><p>The enforced checkout sequence (addresses → shipping → payment methods → place order, with saved-address reuse) is its own page: <strong><a href="/api/workflows/shop/checkout.html">Checkout workflow →</a></strong>.</p><h2 id="_7-customer-account-post-login" tabindex="-1">7. Customer account (post-login) <a class="header-anchor" href="#_7-customer-account-post-login" aria-label="Permalink to &quot;7. Customer account (post-login)&quot;">​</a></h2><ul><li><strong>Profile &amp; addresses</strong> — the <a href="/api/rest-api/shop/customers/">Customers</a> endpoints: <a href="/api/rest-api/shop/customers/get-customer-addresses.html">addresses</a>, <a href="/api/rest-api/shop/customers/change-password.html">change password</a>.</li><li><strong>Orders</strong> — <a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Customer Orders</a> · <a href="/api/rest-api/shop/customer-orders/get-customer-order.html">single order</a> for the confirmation + history screens.</li><li><strong>Invoices</strong> — <a href="/api/rest-api/shop/customer-invoices/get-customer-invoices.html">Get Customer Invoices</a> · <a href="/api/rest-api/shop/customer-invoices/download-customer-invoice-pdf.html">download PDF</a>.</li><li><strong>Downloadable products</strong> — <a href="/api/rest-api/shop/customer-downloadable-products/get-customer-downloadable-products.html">Get Downloadable Products</a>.</li><li><strong>GDPR</strong> — <a href="/api/rest-api/shop/gdpr-requests/create-gdpr-request.html">raise</a> / <a href="/api/rest-api/shop/gdpr-requests/list-gdpr-requests.html">list</a> / <a href="/api/rest-api/shop/gdpr-requests/revoke-gdpr-request.html">revoke</a> data requests (config-gated).</li></ul><h2 id="graphql-variant" tabindex="-1">GraphQL variant <a class="header-anchor" href="#graphql-variant" aria-label="Permalink to &quot;GraphQL variant&quot;">​</a></h2><p>Every step has a GraphQL equivalent at <code>POST /api/graphql</code> (see the Shop GraphQL section). On cart / checkout <strong>mutations</strong> select the result fields (cart contents, order id, <code>success</code>, <code>message</code>) — they&#39;re actions, so don&#39;t select an <code>id</code> on them.</p><h2 id="status-codes-to-handle" tabindex="-1">Status codes to handle <a class="header-anchor" href="#status-codes-to-handle" aria-label="Permalink to &quot;Status codes to handle&quot;">​</a></h2><p>Every call below links to its <strong>REST</strong> endpoint page for concreteness. The sequence is transport-agnostic — the same flow works over GraphQL with the equivalent query or mutation, and each REST page cross-links to its GraphQL twin. Pick whichever transport your client uses; only the request shape changes, never the order of steps.</p><p><code>200/201</code> success · <code>401</code> unauthenticated (missing key/token) · <code>403</code> forbidden · <code>400</code> bad input · <code>404</code> not found · <code>422</code> validation (e.g. quantity exceeds stock).</p>',27)]))}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
